def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([5]), fmt([7, 7, 7, 7]), fmt([1, 2, 3, 4, 5]), fmt([5, 4, 3, 2, 1]), fmt([1, 2, 1, 2, 1, 2]), fmt([10**9, 1, 10**9, 1])]
    for n in (2, 3, 5, 8, 10, 15, 20, 30):
        for v in (2, 4):
            tests.append(fmt([rng.randint(1, v) for _ in range(n)]))
    n = 10**5
    tests.append(fmt([rng.randint(1, 50) for _ in range(n)]))
    tests.append(fmt([rng.randint(1, 10**9) for _ in range(n)]))
    tests.append(fmt([7] * n))
    tests.append(fmt([i % 1000 + 1 for i in range(n)]))
    return tests
